68	/// A single override rule parsed from the root package.json "overrides" field.
69	///
70	/// Represents entries like:
71	/// - `"foo": "1.0.0"` (simple, no selector, no children)
72	/// - `"foo@^2.0.0": { ".": "2.1.0", "bar": "3.0.0" }` (selector + dot + children)
73	#[derive(Debug, Clone)]
74	pub struct NpmOverrideRule {
75	  /// The package name this override targets.
76	  pub name: PackageName,
77	  /// Optional version range selector on the key (e.g. `^2.0.0` from
78	  /// `foo@^2.0.0`). When present, the override only applies when the
79	  /// resolved version satisfies this range.
80	  pub selector: Option<VersionReq>,
81	  /// The override value for this package itself.
82	  pub value: NpmOverrideValue,
83	  /// Nested overrides that apply within this package's dependency subtree.
84	  pub children: Vec<Arc<NpmOverrideRule>>,
85	}
86	
87	/// Top-level parsed overrides from the root package.json.
88	#[derive(Debug, Clone, Default)]
89	pub struct NpmOverrides {
90	  pub rules: Vec<Arc<NpmOverrideRule>>,
91	}
92	
93	impl NpmOverrides {
94	  /// Parses overrides from the raw JSON "overrides" object in package.json.
95	  ///
96	  /// `root_deps` should contain all direct dependencies of the root package
97	  /// (merged from `dependencies`, `devDependencies`, etc.) mapping bare
98	  /// specifier to version string. This is used to resolve `$pkg` references.
99	  pub fn from_value(
100	    value: serde_json::Value,
101	    root_deps: &HashMap<PackageName, StackString>,
102	  ) -> Result<Self, NpmOverridesError> {
103	    match value {
104	      serde_json::Value::Object(map) => {
105	        let rules = parse_override_rules(&map, root_deps)?;
106	        Ok(Self { rules })
107	      }
108	      serde_json::Value::Null => Ok(Self::default()),
109	      _ => Err(NpmOverridesError::InvalidTopLevelType),
110	    }
111	  }
112	
113	  pub fn is_empty(&self) -> bool {
114	    self.rules.is_empty()
115	  }
116	
117	  /// Computes the active overrides for a child node in the dependency tree.
118	  ///
119	  /// When descending into `child_name@child_version`:
120	  /// - Rules that target `child_name` and whose selector matches: their
121	  ///   `children` become active for this subtree. Scoped children are placed
122	  ///   before passthrough rules so they take precedence in lookups.
123	  /// - Rules that target other packages (either simple or scoped): pass
124	  ///   through unchanged so they can match deeper descendants.
125	  pub fn for_child(
126	    self: &Rc<Self>,
127	    child_name: &PackageName,
128	    child_version: &Version,
129	  ) -> Rc<Self> {
130	    if self.rules.is_empty() {
131	      return self.clone();
132	    }
133	
134	    let mut scoped_children: Vec<Arc<NpmOverrideRule>> = Vec::new();
135	    let mut passthrough_rules: Vec<Arc<NpmOverrideRule>> = Vec::new();
136	    let mut changed = false;
137	
138	    for rule in self.rules.iter() {
139	      if rule.name == *child_name {
140	        let selector_matches = match &rule.selector {
141	          Some(selector) => selector.matches(child_version),
142	          None => true,
143	        };
144	
145	        if selector_matches && !rule.children.is_empty() {
146	          // this rule targets the current child and matches; activate its
147	          // nested overrides for this subtree
148	          scoped_children.extend(rule.children.iter().cloned());
149	        }
150	        if rule.children.is_empty()
151	          || (rule.selector.is_some() && !selector_matches)
152	        {
153	          // pass through when: the rule is a simple childless override
154	          // (so it keeps applying deeper), OR the rule has a selector
155	          // that didn't match this version (so it can still match a
156	          // deeper occurrence at a different version)
157	          passthrough_rules.push(rule.clone());
158	        }
159	        changed = true;
160	      } else {
161	        // this rule targets a different package — keep it active for
162	        // deeper descendants
163	        passthrough_rules.push(rule.clone());
164	      }
165	    }
166	
167	    if !changed {
168	      self.clone()
169	    } else {
170	      // scoped children first so they take precedence over passthrough rules
171	      scoped_children.extend(passthrough_rules);
172	      Rc::new(Self {
173	        rules: scoped_children,
174	      })
175	    }
176	  }
