/// Resolves a `catalog:` or `catalog:<name>` override value by looking up the
/// package (derived from the override key) in the named workspace catalog. An
/// empty catalog name resolves to the `"default"` catalog.
fn resolve_catalog_override(
  key: &str,
  catalog_name: &str,
  catalogs: &Catalogs,
) -> Result<NpmOverrideValue, NpmOverridesError> {
  let catalog_name = if catalog_name.is_empty() {
    "default"
  } else {
    catalog_name
  };
  // the override key may include a version selector (e.g. "foo@^1.0.0");
  // only the package name portion is used for the catalog lookup
  let (package_name, _) = parse_override_key(key)?;
  let version = catalogs
    .get(catalog_name)
    .and_then(|catalog| catalog.get(package_name.as_str()))
    .ok_or_else(|| NpmOverridesError::UnresolvedCatalog {
      key: key.to_string(),
      catalog: catalog_name.to_string(),
    })?;
  let version_req = VersionReq::parse_from_npm(version).map_err(|source| {
    NpmOverridesError::ValueParse {
      key: key.to_string(),
      value: version.to_string(),
      source,
    }
  })?;
  Ok(NpmOverrideValue::Version(version_req))
